  embedding_jobs: ['note_id', 'attempts'],
  recall_usage: ['semantic_search_count'],
  recalls: ['search_embedding'],
  tidy_runs: ['instruction', 'pending_plan', 'pending_expires_at', 'confirmed_at'],
  deployment_settings: ['id', 'self_hosted'],
